const feeds = [
  { name: 'TechCrunch', url: 'https://techcrunch.com/feed/' },
  { name: 'Hacker News', url: 'https://hnrss.org/newest?points=100' },
  { name: 'Dev.to', url: 'https://dev.to/feed' }
];
return feeds.map(f => ({ json: f }));

const items = $input.all();
const results = [];
const oneHourAgo = new Date(Date.now() - 60 * 60 * 1000);

for (const item of items) {
  const text = item.json.data || item.json.body || '';
  // Simple XML parsing for RSS items
  const itemRegex = /<item[^>]*>[\s\S]*?<\/item>/g;
  const titleRegex = /<title[^>]*>(?:<\!\[CDATA\[)?(.*?)(?:\]\]>)?<\/title>/;
  const linkRegex = /<link[^>]*>(.*?)<\/link>/;
  const pubDateRegex = /<pubDate[^>]*>(.*?)<\/pubDate>/;
  const descRegex = /<description[^>]*>(?:<\!\[CDATA\[)?(.*?)(?:\]\]>)?<\/description>/;

  let match;
  while ((match = itemRegex.exec(text)) !== null) {
    const itemXml = match[0];
    const title = (titleRegex.exec(itemXml) || [])[1] || 'No title';
    const link = (linkRegex.exec(itemXml) || [])[1] || '';
    const pubDate = (pubDateRegex.exec(itemXml) || [])[1] || '';
    const desc = (descRegex.exec(itemXml) || [])[1] || '';

    const date = new Date(pubDate);
    if (date >= oneHourAgo) {
      results.push({
        json: {
          feedName: item.json.name || 'Unknown',
          title: title.replace(/<[^>]+>/g, '').substring(0, 200),
          link,
          description: desc.replace(/<[^>]+>/g, '').substring(0, 300),
          pubDate: pubDate,
          timestamp: new Date().toISOString()
        }
      });
    }
  }
}
return results.length > 0 ? results.slice(0, 10) : [{ json: { noNews: true } }];
